begin;
create or replace function public.property_ad_test_organization(target_user uuid) returns uuid language plpgsql stable security definer set search_path='' as $$ declare result uuid; begin if not exists(select 1 from auth.users where id=target_user and email='property-ad-owner@example.com') then raise exception 'INVALID PROPERTY AD FIXTURE'; end if; select organization_id into strict result from public.profiles where id=target_user; return result; end $$;
create or replace function public.property_ad_test_snapshot(target_request uuid) returns jsonb language sql stable security definer set search_path='' as $$ select jsonb_build_object('request',to_jsonb(r),'lead',to_jsonb(l),'note',(select n.content from public.lead_notes n where n.lead_id=l.id order by n.created_at desc limit 1)) from public.property_ad_requests r join public.leads l on l.id=r.lead_id where r.id=target_request $$;
create or replace function public.property_ad_test_counts(target_request uuid) returns jsonb language sql stable security definer set search_path='' as $$ select jsonb_build_object('requests',(select count(*) from public.property_ad_requests where id=target_request),'leads',(select count(*) from public.leads l join public.property_ad_requests r on r.lead_id=l.id where r.id=target_request)) $$;
do $$ declare signature text; begin foreach signature in array array['property_ad_test_organization(uuid)','property_ad_test_snapshot(uuid)','property_ad_test_counts(uuid)'] loop execute format('revoke all on function public.%s from public,anon,authenticated',signature);execute format('grant execute on function public.%s to service_role',signature);end loop;end $$;
notify pgrst,'reload schema';
commit;
